/**
 * 会话信息（FFI DTO）
 *
 * 给 Library UI 渲染使用 — 字段从 SessionQueryStore + SessionMetaStore 拼装。
 * 见 D5-uniffi-api §SessionInfo。
 */
public struct SessionInfo: Equatable, Hashable {
    public var id: String
    public var sessionType: String
    public var status: String
    /**
     * 显示标题（导入音频时来自文件名 stem，新会话默认空字符串）
     */
    public var title: String
    /**
     * 时长（毫秒）
     */
    public var durationMs: UInt64
    /**
     * 源语言代码（如 "en"）；尚未设置时为空字符串
     */
    public var sourceLanguage: String
    /**
     * 目标翻译语言代码列表；空表示无翻译
     */
    public var targetLanguages: [String]
    /**
     * 创建时间，Unix 时间戳毫秒（Swift 用 `Date(timeIntervalSince1970:)`）
     */
    public var createdAtUnixMs: UInt64
    /**
     * 是否还有加密音频文件（隐私销毁后可能为 false）
     */
    public var hasEncryptedAudio: Bool
    /**
     * Library 列表预览:transcript 首 ~120 字符(空 = 还没转录 / 没内容)。
     * UI 用来回答"这个 session 在说什么"。
     */
    public var preview: String
    /**
     * 是否在垃圾箱里(TrashPage 用 list_trashed_sessions 专门拿,
     * Home 用 list_sessions 不会返回 trashed 的)。
     */
    public var isTrashed: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, sessionType: String, status: String,
        /**
         * 显示标题（导入音频时来自文件名 stem，新会话默认空字符串）
         */title: String,
        /**
         * 时长（毫秒）
         */durationMs: UInt64,
        /**
         * 源语言代码（如 "en"）；尚未设置时为空字符串
         */sourceLanguage: String,
        /**
         * 目标翻译语言代码列表；空表示无翻译
         */targetLanguages: [String],
        /**
         * 创建时间，Unix 时间戳毫秒（Swift 用 `Date(timeIntervalSince1970:)`）
         */createdAtUnixMs: UInt64,
        /**
         * 是否还有加密音频文件（隐私销毁后可能为 false）
         */hasEncryptedAudio: Bool,
        /**
         * Library 列表预览:transcript 首 ~120 字符(空 = 还没转录 / 没内容)。
         * UI 用来回答"这个 session 在说什么"。
         */preview: String,
        /**
         * 是否在垃圾箱里(TrashPage 用 list_trashed_sessions 专门拿,
         * Home 用 list_sessions 不会返回 trashed 的)。
         */isTrashed: Bool) {
        self.id = id
        self.sessionType = sessionType
        self.status = status
        self.title = title
        self.durationMs = durationMs
        self.sourceLanguage = sourceLanguage
        self.targetLanguages = targetLanguages
        self.createdAtUnixMs = createdAtUnixMs
        self.hasEncryptedAudio = hasEncryptedAudio
        self.preview = preview
        self.isTrashed = isTrashed
    }




}

