/**
 * FFI 编辑操作
 */

public enum FfiEditOp: Equatable, Hashable {

    case insert(pos: UInt64, text: String
    )
    case delete(pos: UInt64, len: UInt64
    )
    case replace(pos: UInt64, len: UInt64, text: String
    )
    /**
     * 富文本标记:在 [pos, pos+len) 范围加 key=value 的属性
     * value_json 是 JSON 序列化的属性值("true" / "1" / "\"#ff0000\"")
     */
    case mark(pos: UInt64, len: UInt64, key: String, valueJson: String
    )
    /**
     * 移除 [pos, pos+len) 范围上的 key 属性
     */
    case unmark(pos: UInt64, len: UInt64, key: String
    )





}

#if compiler(>=6)
extension FfiEditOp: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiEditOp: FfiConverterRustBuffer {
    typealias SwiftType = FfiEditOp

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiEditOp {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .insert(pos: try FfiConverterUInt64.read(from: &buf), text: try FfiConverterString.read(from: &buf)
        )

        case 2: return .delete(pos: try FfiConverterUInt64.read(from: &buf), len: try FfiConverterUInt64.read(from: &buf)
        )

        case 3: return .replace(pos: try FfiConverterUInt64.read(from: &buf), len: try FfiConverterUInt64.read(from: &buf), text: try FfiConverterString.read(from: &buf)
        )

        case 4: return .mark(pos: try FfiConverterUInt64.read(from: &buf), len: try FfiConverterUInt64.read(from: &buf), key: try FfiConverterString.read(from: &buf), valueJson: try FfiConverterString.read(from: &buf)
        )

        case 5: return .unmark(pos: try FfiConverterUInt64.read(from: &buf), len: try FfiConverterUInt64.read(from: &buf), key: try FfiConverterString.read(from: &buf)
        )

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiEditOp, into buf: inout [UInt8]) {
        switch value {


        case let .insert(pos,text):
            writeInt(&buf, Int32(1))
            FfiConverterUInt64.write(pos, into: &buf)
            FfiConverterString.write(text, into: &buf)


        case let .delete(pos,len):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(pos, into: &buf)
            FfiConverterUInt64.write(len, into: &buf)


        case let .replace(pos,len,text):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(pos, into: &buf)
            FfiConverterUInt64.write(len, into: &buf)
            FfiConverterString.write(text, into: &buf)


        case let .mark(pos,len,key,valueJson):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(pos, into: &buf)
            FfiConverterUInt64.write(len, into: &buf)
            FfiConverterString.write(key, into: &buf)
            FfiConverterString.write(valueJson, into: &buf)


        case let .unmark(pos,len,key):
            writeInt(&buf, Int32(5))
            FfiConverterUInt64.write(pos, into: &buf)
            FfiConverterUInt64.write(len, into: &buf)
            FfiConverterString.write(key, into: &buf)

        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeFfiEditOp_lift(_ buf: RustBuffer) throws -> FfiEditOp {
    return try FfiConverterTypeFfiEditOp.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeFfiEditOp_lower(_ value: FfiEditOp) -> RustBuffer {
    return FfiConverterTypeFfiEditOp.lower(value)
}


